-- ========================================================





-- ========================================================


function Live3D_14900850_demo:__init(  )
end


-- 需手动调用 Delete()
function Live3D_14900850_demo:__delete()
end


function Live3D_14900850_demo:OnDestroy()

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- ====================================================== 

-- 在 mainForRuntime Init() 尾部被调用
function Live3D_14900850_demo:OnMainInitEnd( mainForRuntime_ ) 

    self.mainForRuntime = mainForRuntime_
    self.uiMain = mainForRuntime_.uiMain  -- Env
    self.uiMainTF = self.uiMain.controller.gameObject.transform
    self.baseJson = mainForRuntime_.baseJson
    ---
    self.clothSceneNodes = self.mainForRuntime.idolLive3D_FreeNodesMgr:FindNodes("c_", "cloth")
    self:ShowCloths(false)

    --- 
    local allResources = self.mainForRuntime.idolLive3D_InteractiveManagerEnv.allResources
    self.fullScreenFXEnv = allResources.fullScreenFXEnvs["_FullBlack_"]

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = cs_coroutine.start(function()
        cs_coroutine.yield_return( self.fullScreenFXEnv:FadeIn( 0 ) ) --- 全屏特效 淡入
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.8 ))
        cs_coroutine.yield_return( self.fullScreenFXEnv:FadeOut() ) -- 全屏特效 淡出
    end)
end

function Live3D_14900850_demo:ShowCloths( isShow_ ) 
    for _,node in pairs(self.clothSceneNodes) do 
        CfUtils.SetActive( node.transform.gameObject, isShow_ )
    end 
end



return Live3D_14900850_demo
